function beep(freq,duration){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();let osc=audio.createOscillator(),gain=audio.createGain();osc.frequency.value=freq;osc.type='sine';gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+duration);}catch{}}
function action(a){if(!run||paused)return;if(a==='left')lane=Math.max(0,lane-1);if(a==='right')lane=Math.min(2,lane+1);if(a==='jump'&&jump<=0&&slide<=0){jump=.82;if(soundOn)beep(480,.08);}if(a==='slide'&&jump<=0){slide=.72;if(soundOn)beep(260,.07);}}
function startRun(){entities=[];particles=[];distance=0;coins=0;speed=18;lane=1;playerLane=1;jump=slide=0;spawnAt=25;run=true;paused=false;dead=false;ui.coins.textContent='◉ 0';ui.score.textContent='000000';ui.overlay.classList.add('hidden');last=performance.now();}
function endRun(){if(dead)return;run=false;dead=true;best=Math.max(best,Math.floor(distance));localStorage.setItem('neonRunBest',best);ui.eyebrow.textContent='RUN COMPLETE  ·  BEST '+String(best).padStart(6,'0');ui.title.innerHTML='ONE MORE<br><span>RUN?</span>';ui.message.innerHTML=`You made it <b style="color:#ffcb64">${Math.floor(distance)} m</b> and collected <b style="color:#62f2ed">${coins} coins</b>. The night line is still moving.`;ui.start.textContent='RUN IT BACK  ↗';setTimeout(()=>ui.overlay.classList.remove('hidden'),420);}
function drawParticles(dt){for(const p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=210*dt;p.life-=dt;ctx.globalAlpha=Math.max(0,p.life/.55);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3);}ctx.globalAlpha=1;particles=particles.filter(p=>p.life>0);}
function drawVignette(){let g=ctx.createRadialGradient(W/2,H*.48,Math.min(W,H)*.18,W/2,H*.48,Math.max(W,H)*.74);g.addColorStop(0,'#020a1400');g.addColorStop(1,'#020a1455');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);}
function frame(t){requestAnimationFrame(frame);let dt=Math.min(.04,(t-last)/1000||0);last=t;now=t/1000;if(run&&!paused){distance+=speed*dt;speed=Math.min(31,18+distance*.013);if(distance>=spawnAt)spawnWave();playerLane+=(lane-playerLane)*Math.min(1,dt*13);jump=Math.max(0,jump-dt);slide=Math.max(0,slide-dt);updateEntities(dt);ui.score.textContent=String(Math.floor(distance*10)).padStart(6,'0');}
world();entities.sort((a,b)=>b.z-a.z);for(const e of entities){if(e.kind==='coin')drawCoin(e);else drawObstacle(e);}drawPlayer();drawParticles(dt);drawVignette();}
requestAnimationFrame(frame);
ui.start.addEventListener('click',startRun);
addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowleft','arrowright','arrowup','arrowdown',' '].includes(k))e.preventDefault();if(!run){if(k==='enter'||k===' ')startRun();return;}if(k==='arrowleft'||k==='a')action('left');if(k==='arrowright'||k==='d')action('right');if(k==='arrowup'||k==='w'||k===' ')action('jump');if(k==='arrowdown'||k==='s')action('slide');if(k==='escape'||k==='p'){paused=!paused;if(paused){run=false;ui.eyebrow.textContent='PAUSED';ui.title.innerHTML='CATCH YOUR<br><span>BREATH</span>';ui.message.textContent='The night line can wait. Take a moment, then jump back in.';ui.start.textContent='RESUME RUN  ↗';ui.overlay.classList.remove('hidden');}else{run=true;ui.overlay.classList.add('hidden');last=performance.now();}}});
